#!/usr/bin/env bash
# mouli : testeur libft non officiel (sujet v19.3), installateur en un seul fichier.
#   bash install_mouli.sh              installe ou met à jour (dans ~/.mouli)
#   bash install_mouli.sh --uninstall  désinstalle
# La suite du fichier est le testeur lui-même (archive tar.gz encodée en base64).
set -e
if ! command -v python3 >/dev/null 2>&1; then
	echo "mouli : python3 est introuvable (il est installé sur les postes 42)." >&2
	exit 1
fi
TMP="$(mktemp -d "${TMPDIR:-/tmp}/mouli-install.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
sed '1,/^__ARCHIVE_MOULI__$/d' "$0" \
	| python3 -c 'import base64, sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' \
	| tar -xzf - -C "$TMP"
bash "$TMP/mouli/install.sh" "$@"
exit $?
